insert into public.places (id, name, cat, cats, city, lat, lon, description, photo_url, created_by) values
  ('p1', 'El Infiernillo', 'surf', ARRAY['surf']::text[], 'Pichilemu', -34.3897, -72.0056, 'Rompiente izquierda de clase mundial, ideal para nivel intermedio-avanzado. Mejor con marea baja y swell del suroeste.', 'fotos/lugar-p1.jpg', NULL),
  ('p2', 'Mirador del Cóndor', 'trekking', ARRAY['trekking']::text[], 'San Ramón, Santiago', -33.5333, -70.5333, 'Vista completa de la cuenca de Santiago tras una subida exigente de 2 horas. Llevar agua y salir temprano.', 'fotos/lugar-p2.jpg', NULL),
  ('p3', 'Sendero Cajón del Maipo', 'trekking', ARRAY['trekking']::text[], 'San José de Maipo', -33.65, -70.35, 'Recorrido junto al río hasta un mirador glaciar. Dificultad media, apto para grupos con algo de experiencia.', 'fotos/lugar-p3.jpg', NULL),
  ('p4', 'Skatepark Bellavista', 'skate', ARRAY['skate']::text[], 'Santiago', -33.43, -70.628, 'Bowl y street plaza al aire libre, activo todas las tardes. Buena onda para principiantes también.', 'fotos/lugar-p4.jpg', NULL),
  ('p5', 'La Esquina de Valpo', 'comida', ARRAY['comida']::text[], 'Valparaíso', -33.0458, -71.6197, 'Cocina de mercado con vista al puerto. La sopa marinera del día siempre vale la pena.', 'fotos/lugar-p5.jpg', NULL),
  ('p6', 'Playa Grande de Concón', 'playas', ARRAY['playas']::text[], 'Concón', -32.927, -71.531, 'Extensa playa de arena fina, buena para caminatas largas y atardeceres.', NULL, NULL),
  ('p7', 'Termas Escondidas', 'naturaleza', ARRAY['naturaleza']::text[], 'Cajón del Maipo', -33.75, -70.28, 'Pozones naturales alimentados por una vertiente. Acceso caminando 40 minutos desde el estacionamiento.', NULL, NULL),
  ('p8', 'Cancha Techada Ñuñoa', 'futbol', ARRAY['futbol']::text[], 'Ñuñoa, Santiago', -33.456, -70.599, 'Cancha de fútbol 7 techada, arriendo por hora. Se arman pichangas abiertas los martes.', NULL, NULL),
  ('p9', 'Valle de la Luna', 'naturaleza', ARRAY['naturaleza']::text[], 'San Pedro de Atacama', -22.9098, -68.2827, 'Formaciones de sal y arcilla que parecen otro planeta. El mejor momento es el atardecer, cuando el valle se pone rosado.', 'fotos/lugar-p9.jpg', NULL),
  ('p10', 'Mirador Torres del Paine', 'trekking', ARRAY['trekking']::text[], 'Parque Nacional Torres del Paine', -50.9423, -73.0369, 'La vista clásica de las tres torres de granito sobre la laguna. Se llega tras una caminata exigente de día completo.', 'fotos/lugar-p10.jpg', NULL),
  ('cl1', 'Cerro Manquehue', 'montana', ARRAY['montana','trekking','mirador']::text[], 'Vitacura, Santiago', -33.356616, -70.593166, 'Cerro emblemático del sector oriente de Santiago, con una subida exigente de un par de horas y vistas de 360° de la cordillera y la ciudad.', 'fotos/lugar-cl1.jpg', NULL),
  ('cl2', 'Cerro San Cristóbal', 'montana', ARRAY['montana','mirador','naturaleza']::text[], 'Recoleta, Santiago', -33.420344, -70.629896, 'El gran parque urbano de Santiago, con funicular, teleférico y senderos hasta el Santuario de la Inmaculada Concepción.', 'fotos/lugar-cl2.jpg', NULL),
  ('cl3', 'Sky Costanera', 'mirador', ARRAY['mirador','cultura']::text[], 'Providencia, Santiago', -33.416722, -70.606835, 'Mirador en el piso 61-62 de la torre más alta de Sudamérica, con vista panorámica de Santiago y la cordillera de los Andes.', 'fotos/lugar-cl3.jpg', NULL),
  ('cl4', 'Cajón del Maipo', 'trekking', ARRAY['trekking','naturaleza']::text[], 'San José de Maipo', -33.83363, -70.116288, 'Valle cordillerano a las puertas de Santiago, punto de partida para senderos, termas y montañismo.', NULL, NULL),
  ('cl5', 'Embalse El Yeso', 'naturaleza', ARRAY['naturaleza','trekking']::text[], 'San José de Maipo', -33.65107, -70.081035, 'Laguna artificial de aguas turquesa rodeada de montañas, uno de los paisajes más fotografiados de la Región Metropolitana.', 'fotos/lugar-cl5.jpg', NULL),
  ('cl6', 'Valle Nevado', 'montana', ARRAY['montana','aventura']::text[], 'Cordillera de Santiago', -33.354348, -70.249156, 'Centro de esquí y montaña a 46 km de Santiago, con pistas de nivel internacional y vistas de alta cordillera.', NULL, NULL),
  ('cl7', 'Farellones', 'montana', ARRAY['montana','aventura']::text[], 'Cordillera de Santiago', -33.350796, -70.312941, 'Pueblo de montaña puerta de entrada a los centros de esquí de la zona central, con trekking y actividades todo el año.', 'fotos/lugar-cl7.jpg', NULL),
  ('cl8', 'Viña del Mar', 'playas', ARRAY['playas','cultura']::text[], 'Viña del Mar', -33.024453, -71.551764, 'La ''Ciudad Jardín'', con extensas playas, el Reloj de Flores y una animada vida cultural en la costa central.', 'fotos/lugar-cl8.jpg', NULL),
  ('cl9', 'Valparaíso', 'cultura', ARRAY['cultura','mirador']::text[], 'Valparaíso', -33.037466, -71.627097, 'Puerto patrimonial de la UNESCO, de cerros, ascensores históricos y arte callejero con vista a la bahía.', 'fotos/lugar-cl9.jpg', NULL),
  ('cl10', 'Dunas de Concón', 'naturaleza', ARRAY['naturaleza','playas']::text[], 'Concón', -32.922004, -71.515957, 'Gigantescas dunas de arena junto al mar, un paisaje desértico costero único a minutos de Viña del Mar.', NULL, NULL),
  ('cl11', 'Roca Oceánica', 'mirador', ARRAY['mirador','naturaleza']::text[], 'Concón', -32.941379, -71.554105, 'Mirador natural sobre acantilados donde el río Aconcagua se encuentra con el océano Pacífico.', NULL, NULL),
  ('cl12', 'Pichilemu', 'surf', ARRAY['surf','playas']::text[], 'Pichilemu', -34.385169, -72.004661, 'Capital chilena del surf, con olas de nivel mundial y un ambiente costero relajado.', NULL, NULL),
  ('cl13', 'Playa La Puntilla', 'playas', ARRAY['playas','surf']::text[], 'Pichilemu', -34.381499, -72.015424, 'Playa principal de Pichilemu, ideal para iniciarse en el surf y disfrutar del atardecer.', NULL, NULL),
  ('cl14', 'Punta de Lobos', 'surf', ARRAY['surf','mirador']::text[], 'Pichilemu', -34.429275, -72.037568, 'Una de las mejores rompientes de Sudamérica, con un acantilado icónico y atardeceres inolvidables.', NULL, NULL),
  ('cl15', 'San Pedro de Atacama', 'cultura', ARRAY['cultura','astroturismo']::text[], 'San Pedro de Atacama', -23.354549, -67.902657, 'Oasis y pueblo ancestral en pleno desierto de Atacama, puerta de entrada a los principales atractivos del altiplano.', NULL, NULL),
  ('cl16', 'Valle de la Luna', 'naturaleza', ARRAY['naturaleza','mirador','astroturismo']::text[], 'San Pedro de Atacama', -22.931621, -68.308723, 'Formaciones de sal y arcilla que recuerdan un paisaje lunar; el atardecer tiñe el valle de tonos rosados.', 'fotos/lugar-cl16.jpg', NULL),
  ('cl17', 'Géiseres del Tatio', 'naturaleza', ARRAY['naturaleza','astroturismo']::text[], 'San Pedro de Atacama', -22.341705, -68.01171, 'El campo geotérmico más alto del mundo, mejor visitado al amanecer cuando las fumarolas son más intensas.', 'fotos/lugar-cl17.jpg', NULL),
  ('cl18', 'Piedras Rojas', 'naturaleza', ARRAY['naturaleza','mirador']::text[], 'San Pedro de Atacama', -23.921325, -67.6964, 'Salar y laguna altiplánica bordeada de formaciones rocosas rojizas a más de 4.000 msnm.', NULL, NULL),
  ('cl19', 'Lagunas Altiplánicas', 'naturaleza', ARRAY['naturaleza']::text[], 'San Pedro de Atacama', -23.727452, -67.766912, 'Las lagunas Miscanti y Miñiques, de un azul profundo enmarcadas por volcanes, en plena Reserva Los Flamencos.', NULL, NULL),
  ('cl20', 'Salar de Atacama', 'naturaleza', ARRAY['naturaleza']::text[], 'San Pedro de Atacama', -23.383623, -68.256672, 'El mayor salar de Chile, hogar de flamencos andinos y paisajes de una blancura extrema.', NULL, NULL),
  ('cl21', 'Termas de Puritama', 'naturaleza', ARRAY['naturaleza']::text[], 'San Pedro de Atacama', -22.720034, -68.043532, 'Ocho pozones de aguas termales naturales en una quebrada del desierto, rodeadas de vegetación.', NULL, NULL),
  ('cl22', 'La Portada', 'naturaleza', ARRAY['naturaleza','mirador']::text[], 'Antofagasta', -23.498753, -70.424423, 'Monumento natural con un arco rocoso emblemático esculpido por el mar frente a la costa de Antofagasta.', 'fotos/lugar-cl22.jpg', NULL),
  ('cl23', 'Morro de Arica', 'mirador', ARRAY['mirador','cultura']::text[], 'Arica', -18.480088, -70.324026, 'Promontorio histórico que domina la ciudad de Arica, con museo y vistas al océano y al valle de Azapa.', 'fotos/lugar-cl23.jpg', NULL),
  ('cl24', 'Lago Chungará', 'naturaleza', ARRAY['naturaleza','montana']::text[], 'Parque Nacional Lauca', -18.310846, -69.135747, 'Uno de los lagos navegables más altos del mundo, a los pies del volcán Parinacota.', 'fotos/lugar-cl24.jpg', NULL),
  ('cl25', 'Parque Nacional Lauca', 'naturaleza', ARRAY['naturaleza','trekking']::text[], 'Región de Arica y Parinacota', -18.261353, -69.291206, 'Altiplano chileno con volcanes, vicuñas y bofedales, Reserva de la Biósfera de la UNESCO.', NULL, NULL),
  ('cl26', 'Pucón', 'aventura', ARRAY['aventura','naturaleza']::text[], 'Pucón', -39.273117, -71.977761, 'Capital turística de la Araucanía, entre el volcán Villarrica y el lago del mismo nombre.', NULL, NULL),
  ('cl27', 'Volcán Villarrica', 'volcan', ARRAY['volcan','trekking']::text[], 'Pucón', -39.421025, -71.939563, 'Uno de los volcanes activos más visitados de Chile, con ascensiones guiadas hasta el cráter humeante.', 'fotos/lugar-cl27.jpg', NULL),
  ('cl28', 'Lago Villarrica', 'naturaleza', ARRAY['naturaleza','acuaticos']::text[], 'Villarrica', -39.255332, -72.085733, 'Lago cordillerano rodeado de volcanes, ideal para deportes acuáticos y playas de arena volcánica.', NULL, NULL),
  ('cl29', 'Frutillar', 'cultura', ARRAY['cultura','naturaleza']::text[], 'Frutillar', -41.125846, -73.060474, 'Pueblo de raíces alemanas a orillas del lago Llanquihue, con el volcán Osorno de telón de fondo.', 'fotos/lugar-cl29.jpg', NULL),
  ('cl30', 'Puerto Varas', 'cultura', ARRAY['cultura','naturaleza']::text[], 'Puerto Varas', -41.317802, -72.982907, 'La ''Ciudad de las Rosas'', centro turístico de la región de los lagos frente al volcán Osorno.', NULL, NULL),
  ('cl31', 'Lago Llanquihue', 'naturaleza', ARRAY['naturaleza','acuaticos']::text[], 'Región de los Lagos', -41.14299, -72.806201, 'El segundo lago más grande de Chile, con vistas a los volcanes Osorno y Calbuco.', NULL, NULL),
  ('cl32', 'Saltos del Petrohué', 'naturaleza', ARRAY['naturaleza','mirador']::text[], 'Parque Nacional Vicente Pérez Rosales', -41.173196, -72.450234, 'Cascadas de roca volcánica sobre el río Petrohué, con el volcán Osorno como telón de fondo.', 'fotos/lugar-cl32.jpg', NULL),
  ('cl33', 'Parque Nacional Vicente Pérez Rosales', 'trekking', ARRAY['trekking','naturaleza']::text[], 'Región de los Lagos', -41.059824, -72.169008, 'El parque nacional más antiguo de Chile, con bosque nativo, lagos y el volcán Osorno.', NULL, NULL),
  ('cl34', 'Castro', 'cultura', ARRAY['cultura']::text[], 'Isla de Chiloé', -42.482375, -73.764292, 'Capital de Chiloé, famosa por sus palafitos coloridos y sus iglesias de madera Patrimonio de la Humanidad.', NULL, NULL),
  ('cl35', 'Parque Nacional Chiloé', 'trekking', ARRAY['trekking','naturaleza']::text[], 'Isla de Chiloé', -42.472561, -74.096615, 'Bosque valdiviano y dunas costeras en la costa oeste de la isla grande de Chiloé.', NULL, NULL),
  ('cl36', 'Puerto Natales', 'cultura', ARRAY['cultura','aventura']::text[], 'Puerto Natales', -51.7262, -72.505998, 'Puerta de entrada a Torres del Paine, a orillas del fiordo Última Esperanza.', NULL, NULL),
  ('cl37', 'Parque Nacional Torres del Paine', 'trekking', ARRAY['trekking','naturaleza','montana']::text[], 'Última Esperanza', -51.040578, -72.984525, 'Uno de los parques nacionales más espectaculares del mundo, con torres de granito, glaciares y estepa patagónica.', 'fotos/lugar-cl37.jpg', NULL),
  ('cl38', 'Mirador Base Las Torres', 'trekking', ARRAY['trekking','mirador']::text[], 'Torres del Paine', -50.942668, -72.949663, 'El mirador más icónico del parque: las tres torres de granito reflejadas en una laguna glaciar, tras un día completo de caminata.', 'fotos/lugar-cl38.jpg', NULL),
  ('cl39', 'Lago Grey', 'naturaleza', ARRAY['naturaleza','acuaticos']::text[], 'Torres del Paine', -51.045797, -73.169713, 'Lago glaciar de aguas turquesa con témpanos de hielo desprendidos del glaciar Grey.', 'fotos/lugar-cl39.jpg', NULL),
  ('cl40', 'Glaciar Grey', 'naturaleza', ARRAY['naturaleza']::text[], 'Torres del Paine', -50.997273, -73.234699, 'Uno de los principales glaciares del Campo de Hielo Sur, visible desde el lago y senderos del parque.', 'fotos/lugar-cl40.jpg', NULL),
  ('cl41', 'Valle del Francés', 'trekking', ARRAY['trekking','naturaleza']::text[], 'Torres del Paine', -50.999399, -73.054772, 'Valle central del circuito W, con vistas al glaciar colgante y a los Cuernos del Paine.', NULL, NULL),
  ('cl42', 'Cuernos del Paine', 'montana', ARRAY['montana','mirador']::text[], 'Torres del Paine', -50.977946, -72.884783, 'Formación de granito y sedimento oscuro, una de las siluetas montañosas más reconocibles de la Patagonia.', 'fotos/lugar-cl42.jpg', NULL),
  ('cl43', 'Villa Cerro Castillo', 'trekking', ARRAY['trekking','naturaleza']::text[], 'Región de Aysén', -46.122616, -72.154366, 'Pueblo al pie del imponente cerro Castillo, con uno de los treks más espectaculares de la Carretera Austral.', 'fotos/lugar-cl43.jpg', NULL),
  ('cl44', 'Carretera Austral', 'aventura', ARRAY['aventura','naturaleza']::text[], 'Región de Aysén', -46.564416, -72.712545, 'Ruta escénica de más de 1.200 km entre bosques, fiordos y glaciares en la Patagonia chilena.', 'fotos/lugar-cl44.jpg', NULL),
  ('cl45', 'Capillas de Mármol', 'naturaleza', ARRAY['naturaleza','acuaticos','mirador']::text[], 'Puerto Río Tranquilo', -46.658862, -72.62842, 'Formaciones de mármol esculpidas por el lago General Carrera, visitables en bote o kayak.', 'fotos/lugar-cl45.jpg', NULL)
